create table public.audit_log (
  id serial not null,
  admin_id integer null,
  tabel_terkait character varying(50) not null,
  record_id integer not null,
  aksi character varying(30) not null,
  catatan text null,
  created_at timestamp without time zone null default now(),
  constraint audit_log_pkey primary key (id),
  constraint audit_log_admin_id_fkey foreign KEY (admin_id) references users (id)
) TABLESPACE pg_default;

create table public.benchmark_margin_tengkulak (
  id serial not null,
  komoditas_id integer null,
  desa_id integer null,
  margin_persen_min numeric(5, 2) not null,
  margin_persen_max numeric(5, 2) not null,
  sumber_referensi text not null,
  catatan text null,
  created_at timestamp without time zone null default now(),
  constraint benchmark_margin_tengkulak_pkey primary key (id),
  constraint benchmark_margin_tengkulak_desa_id_fkey foreign KEY (desa_id) references desa (id),
  constraint benchmark_margin_tengkulak_komoditas_id_fkey foreign KEY (komoditas_id) references komoditas (id)
) TABLESPACE pg_default;

create index IF not exists idx_benchmark_komoditas_desa on public.benchmark_margin_tengkulak using btree (komoditas_id, desa_id) TABLESPACE pg_default;

create table public.desa (
  id serial not null,
  nama_desa character varying(100) not null,
  latitude numeric(9, 6) null,
  longitude numeric(9, 6) null,
  skor_konsistensi numeric(5, 2) null default 100.00,
  constraint desa_pkey primary key (id)
) TABLESPACE pg_default;

create table public.fair_share_distribution (
  id serial not null,
  order_id integer null,
  petani_id integer null,
  intake_grading_id integer null,
  kontribusi_kg numeric(10, 2) not null,
  pengali_grade numeric(3, 2) not null,
  jumlah_diterima numeric(12, 2) not null,
  created_at timestamp without time zone null default now(),
  constraint fair_share_distribution_pkey primary key (id),
  constraint fair_share_distribution_intake_grading_id_fkey foreign KEY (intake_grading_id) references intake_grading (id),
  constraint fair_share_distribution_order_id_fkey foreign KEY (order_id) references orders (id),
  constraint fair_share_distribution_petani_id_fkey foreign KEY (petani_id) references users (id)
) TABLESPACE pg_default;

create index IF not exists idx_fair_share_petani on public.fair_share_distribution using btree (petani_id) TABLESPACE pg_default;

create index IF not exists idx_fair_share_order on public.fair_share_distribution using btree (order_id) TABLESPACE pg_default;

create table public.harga_acuan (
  id serial not null,
  komoditas_id integer null,
  harga_referensi_per_kg numeric(10, 2) not null,
  sumber character varying(100) null,
  tanggal date null default CURRENT_DATE,
  constraint harga_acuan_pkey primary key (id),
  constraint harga_acuan_komoditas_id_fkey foreign KEY (komoditas_id) references komoditas (id)
) TABLESPACE pg_default;

create table public.intake_grading (
  id serial not null,
  stok_estimasi_id integer null,
  petugas_id integer null,
  foto_url text not null,
  skor_warna numeric(3, 2) null,
  skor_ukuran numeric(3, 2) null,
  persen_cacat numeric(5, 2) null,
  grade character(1) null,
  grade_override_manual boolean null default false,
  berat_aktual_kg numeric(10, 2) not null,
  kejanggalan_terdeteksi boolean null default false,
  created_at timestamp without time zone null default now(),
  constraint intake_grading_pkey primary key (id),
  constraint intake_grading_petugas_id_fkey foreign KEY (petugas_id) references users (id),
  constraint intake_grading_stok_estimasi_id_fkey foreign KEY (stok_estimasi_id) references stok_estimasi (id),
  constraint intake_grading_grade_check check (
    (
      grade = any (array['A'::bpchar, 'B'::bpchar, 'C'::bpchar])
    )
  )
) TABLESPACE pg_default;

create index IF not exists idx_intake_grading_petugas on public.intake_grading using btree (petugas_id) TABLESPACE pg_default;

create index IF not exists idx_intake_grading_stok_estimasi on public.intake_grading using btree (stok_estimasi_id) TABLESPACE pg_default;

create table public.komoditas (
  id serial not null,
  nama_komoditas character varying(50) not null,
  satuan character varying(10) null default 'kg'::character varying,
  constraint komoditas_pkey primary key (id)
) TABLESPACE pg_default;

create table public.kopdes (
  id serial not null,
  desa_id integer null,
  nama_kopdes character varying(100) not null,
  fee_persen numeric(5, 2) not null default 0,
  aktif boolean null default true,
  constraint kopdes_pkey primary key (id),
  constraint kopdes_desa_id_fkey foreign KEY (desa_id) references desa (id),
  constraint kopdes_fee_persen_check check (
    (
      (fee_persen >= (0)::numeric)
      and (fee_persen <= (100)::numeric)
    )
  )
) TABLESPACE pg_default;

create table public.order_allocation (
  id serial not null,
  order_id integer null,
  desa_id integer null,
  jumlah_dialokasikan_kg numeric(10, 2) not null,
  urutan_prioritas integer null,
  skor_prioritas numeric(6, 4) null,
  constraint order_allocation_pkey primary key (id),
  constraint order_allocation_desa_id_fkey foreign KEY (desa_id) references desa (id),
  constraint order_allocation_order_id_fkey foreign KEY (order_id) references orders (id)
) TABLESPACE pg_default;

create index IF not exists idx_order_allocation_order on public.order_allocation using btree (order_id) TABLESPACE pg_default;

create index IF not exists idx_order_allocation_desa on public.order_allocation using btree (desa_id) TABLESPACE pg_default;

create table public.orders (
  id serial not null,
  pembeli_id integer null,
  komoditas_id integer null,
  kopdes_id integer null,
  jumlah_diminta_kg numeric(10, 2) not null,
  status character varying(30) null default 'dikonfirmasi_sementara'::character varying,
  harga_final_per_kg numeric(10, 2) null,
  fee_kopdes_persen_terpakai numeric(5, 2) null,
  harga_terkunci boolean null default false,
  created_at timestamp without time zone null default now(),
  updated_at timestamp without time zone null default now(),
  constraint orders_pkey primary key (id),
  constraint orders_komoditas_id_fkey foreign KEY (komoditas_id) references komoditas (id),
  constraint orders_kopdes_id_fkey foreign KEY (kopdes_id) references kopdes (id),
  constraint orders_pembeli_id_fkey foreign KEY (pembeli_id) references users (id)
) TABLESPACE pg_default;

create index IF not exists idx_orders_status on public.orders using btree (status) TABLESPACE pg_default;

create index IF not exists idx_orders_komoditas on public.orders using btree (komoditas_id) TABLESPACE pg_default;

create index IF not exists idx_orders_kopdes on public.orders using btree (kopdes_id) TABLESPACE pg_default;

create index IF not exists idx_orders_pembeli on public.orders using btree (pembeli_id) TABLESPACE pg_default;

create trigger trg_prevent_harga_final_update BEFORE
update on orders for EACH row
execute FUNCTION prevent_harga_final_update ();

create table public.refresh_tokens (
  id serial not null,
  user_id integer not null,
  token_hash text not null,
  expires_at timestamp with time zone not null,
  created_at timestamp with time zone null default now(),
  revoked_at timestamp with time zone null,
  constraint refresh_tokens_pkey primary key (id),
  constraint refresh_tokens_user_id_fkey foreign KEY (user_id) references users (id) on delete CASCADE
) TABLESPACE pg_default;

create index IF not exists idx_refresh_tokens_user_id on public.refresh_tokens using btree (user_id) TABLESPACE pg_default;

create index IF not exists idx_refresh_tokens_token_hash on public.refresh_tokens using btree (token_hash) TABLESPACE pg_default;

create index IF not exists idx_refresh_tokens_expires_at on public.refresh_tokens using btree (expires_at) TABLESPACE pg_default;

create table public.stok_estimasi (
  id serial not null,
  petani_id integer null,
  komoditas_id integer null,
  jumlah_kg numeric(10, 2) not null,
  tanggal_target_panen date not null,
  status character varying(20) null default 'menunggu_panen'::character varying,
  created_at timestamp without time zone null default now(),
  constraint stok_estimasi_pkey primary key (id),
  constraint stok_estimasi_komoditas_id_fkey foreign KEY (komoditas_id) references komoditas (id),
  constraint stok_estimasi_petani_id_fkey foreign KEY (petani_id) references users (id)
) TABLESPACE pg_default;

create index IF not exists idx_stok_estimasi_petani on public.stok_estimasi using btree (petani_id) TABLESPACE pg_default;

create index IF not exists idx_stok_estimasi_status on public.stok_estimasi using btree (status) TABLESPACE pg_default;

create table public.users (
  id serial not null,
  nama character varying(100) not null,
  role character varying(20) not null,
  desa_id integer null,
  email character varying(100) null,
  password_hash text null,
  skor_konsistensi numeric(5, 2) null default 100.00,
  created_at timestamp without time zone null default now(),
  auth_id uuid null,
  profile_completed boolean null default false,
  constraint users_pkey primary key (id),
  constraint users_auth_id_key unique (auth_id),
  constraint users_email_key unique (email),
  constraint fk_users_desa foreign KEY (desa_id) references desa (id),
  constraint users_role_check check (
    (
      (role)::text = any (
        (
          array[
            'petani'::character varying,
            'petugas_kopdes'::character varying,
            'pembeli'::character varying,
            'admin'::character varying
          ]
        )::text[]
      )
    )
  )
) TABLESPACE pg_default;

create index IF not exists idx_users_desa on public.users using btree (desa_id) TABLESPACE pg_default;

create index IF not exists idx_users_email on public.users using btree (email) TABLESPACE pg_default;


